pub fn stable_unique(values: &[u32]) -> Vec<u32> {
    let mut output = Vec::new();
    for value in values {
        if !output.contains(value) {
            output.push(*value);
        }
    }
    output
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn preserves_first_seen_order() {
        assert_eq!(stable_unique(&[3, 1, 3, 2, 1]), vec![3, 1, 2]);
    }
}
